//dependencies 
import { DaprServer, CommunicationProtocolEnum } from '@dapr/dapr'; 
import fs from 'fs'
//code
const daprHost = "127.0.0.1"; 
const serverHost = "127.0.0.1";
const serverPort = "6002"; 
const daprPort = "3602"; 

start().catch((e) => {
    console.error(e);
    process.exit(1);
});

const shopOrders = []
const pickingOrders = []
const prodOrders = []

async function start() {
    const server = new DaprServer({
        serverHost,
        serverPort,
        communicationProtocol: CommunicationProtocolEnum.HTTP,
        clientOptions: {
            daprHost,
            daprPort, 
        }
    });

    await server.binding.receive('picking-order', async (msg) => {
        console.log(`Received Message picking-order `)
        pickingOrders.push(msg)
        fs.writeFileSync('capture/pickingOrders.json', JSON.stringify(pickingOrders))
    });

    await server.binding.receive('prod-order', async (msg) => {
        console.log(`Received Message prod-order `)
        prodOrders.push(msg)
        fs.writeFileSync('capture/prodOrders.json', JSON.stringify(prodOrders))

    });

    await server.binding.receive('shop-order', async (msg) => {
        console.log(`Received Message shop-order `)
        shopOrders.push(msg)
        fs.writeFileSync('capture/shopOrders.json', JSON.stringify(shopOrders))
    });

    await server.start();
}

